-- Fixed camera dataset patch for dashboard
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

CREATE TABLE IF NOT EXISTS public.taipei_camera (
    city text,
    city_code text,
    district text,
    device_id text,
    road_segment text,
    location text,
    address text,
    violation_type text,
    direction text,
    speed_limit text,
    department text,
    branch text,
    lng double precision,
    lat double precision,
    source_dataset text
);

TRUNCATE TABLE public.taipei_camera;

CREATE TABLE IF NOT EXISTS public.newtaipei_camera (
    city text,
    city_code text,
    district text,
    device_id text,
    road_segment text,
    location text,
    address text,
    violation_type text,
    direction text,
    speed_limit text,
    department text,
    branch text,
    lng double precision,
    lat double precision,
    source_dataset text
);

TRUNCATE TABLE public.newtaipei_camera;

